			}
			code := termsafe.Line(failure.Code)
			if code == "" {
				code = "unknown"
			}
			fmt.Fprintf(w, "      %s (%s)\n", label, code)
		}
		if remaining := n - len(shown); remaining > 0 {
			fmt.Fprintf(w, "      %d more — run with --format json for the rest\n", remaining)
		}
	}
