	git(t, repo, "add", ".")
	git(t, repo, "commit", "-m", "initial")

	snapshot, err := BuildProviderSnapshotWithOptions(
		t.Context(), repo, "test", ProviderSnapshotOptions{MaxParseBytes: 1024},
	)

