// its whole @interface to this).
var objcBareAuditMacroPattern = regexp.MustCompile(`^NS_(?:ASSUME_NONNULL_(?:BEGIN|END)|HEADER_AUDIT_(?:BEGIN|END)\s*\([^)]*\))$`)

