		tier := header.LanguageTiers[name]
		if tier == "" {
			tier = "unknown"
		}
		completeness := header.Completeness.Languages[name]
		fmt.Fprintf(&out, "| %s | %s | %d | %d |\n", name, tier, completeness.Files, completeness.Symbols)
	}

