	}
	// The skips it must not be confused with.
	skips := []PartialFailure{{Code: "E_FILE_TOO_LARGE"}, {Code: "E_MINIFIED"}}
	if got := completenessFailureCount(skips); got != 0 {
		t.Fatalf("completenessFailureCount(skips) = %d, want 0", got)
